package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.*;
import com.ruoyi.medical.persistence.mapper.PermissionMapper;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.util.function.ThrowingSupplier;

/** Explicit, independently approved EVAL originals. Registration refers to an already registered
 * real artifact; it never invents a customer task/document or upgrades a SIM fixture. */
public final class FormalEvaluationCaseOriginals {
 private final JdbcTemplate db;private final EnterpriseAccess access;private final FormalEvaluationJobs jobs;
 private final FormalEvaluationContextPackages packages;private final ResourceReadAuthority resources;
 private final PermissionMapper permissions;private final PermissionAuthority grants;private final PlatformMemberIdentityStatus identities;
 private final DependencyLineage lineage;private final EvaluationRuleAuthority rules;private final PermissionSchema json;private final FormalEvaluationStageInputSchema schema;
 private final JsonMapper parser=JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
 public FormalEvaluationCaseOriginals(DataSource data,EnterpriseAccess access,FormalEvaluationJobs jobs,FormalEvaluationContextPackages packages,ResourceReadAuthority resources,PermissionMapper permissions,PermissionAuthority grants,PlatformMemberIdentityStatus identities,PermissionSchema json,FormalEvaluationStageInputSchema schema,EvaluationRuleAuthority rules,DependencyLineage lineage){this.lineage=lineage;this.rules=rules;db=new JdbcTemplate(data);db.setQueryTimeout(5);this.access=access;this.jobs=jobs;this.packages=packages;this.resources=resources;this.permissions=permissions;this.grants=grants;this.identities=identities;this.json=json;this.schema=schema;}
 public JsonNode register(ApplicationSessionIdentity.Verified subject,String context,JsonNode request)throws Exception{
  schema.validate("Register",request);String run=text(request,"run_id"),step=text(request,"step_id");var artifact=basis(request.required("artifact"));
  var plan=access.execute(subject,a->ThrowingSupplier.of(()->{human(a,context);var j=jobs.original(a,run);node(j,step);authorize(a,j,"agent.author");return packages.plan(a,context,j.projectId(),artifact,FormalEvaluationStageInputSchema.caseRef(FormalEvaluationStageInputSchema.version(request)),schema.digest(FormalEvaluationStageInputSchema.version(request)));}).get());
  var physical=packages.read(subject,plan);var original=schema.read(physical.bytes());schema.validate("Case",original);same(FormalEvaluationStageInputSchema.version(request),FormalEvaluationStageInputSchema.version(original));
  return access.execute(subject,a->ThrowingSupplier.of(()->{human(a,context);var j=jobs.original(a,run);var n=node(j,step);var grant=authorize(a,j,"agent.author");physical.requireCurrent(a);scope(j,n,original);requireRules(a,original);requireLineage(artifact,original);lock(j,step);
   var existing=rows(j.tenantId(),run,step);if(!existing.isEmpty()){var row=one(existing);same(artifact.version_id(),row.get("artifact_id"));same(artifact.content_sha256(),row.get("artifact_sha256"));same(json.canonical(original),row.get("canonical_original"));verifyAudit(j,row,"registration_id","evaluation.case.registered");return view(row);}
   String id=UUID.randomUUID().toString();var receipt=json.object().put("registration_id",id).put("run_id",run).put("step_id",step).put("node_sha256",n.nodeSha256()).put("created_by",a.actorId()).put("original_sha256",hash(original));receipt.set("artifact",json.tree(artifact));receipt.set("physical_original",physical.witness());receipt.set("author_grant",AgentPublicationWitness.tree(grant));String canonical=json.canonical(receipt);audit(j,a.actorId(),id,"evaluation.case.registered",canonical);
   changed(db.update("INSERT INTO formal_evaluation_case_original (tenant_id,project_id,run_id,step_id,registration_id,artifact_id,artifact_sha256,canonical_original,canonical_receipt,receipt_sha256,created_by,created_at,classification,schema_version,schema_manifest_sha256) VALUES (?,?,?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP(6),?,?,?)",j.tenantId(),j.projectId(),run,step,id,artifact.version_id(),artifact.content_sha256(),json.canonical(original),canonical,hash(receipt),a.actorId(),j.classification(),FormalEvaluationStageInputSchema.version(original),schema.digest(FormalEvaluationStageInputSchema.version(original))));return view(one(rows(j.tenantId(),run,step)));
  }).get());
 }
 public JsonNode approve(ApplicationSessionIdentity.Verified subject,String context,String registration,JsonNode request)throws Exception{
  WireValues.uuid(registration);schema.validate("Approve",request);
  return access.execute(subject,a->ThrowingSupplier.of(()->{human(a,context);var row=one(db.queryForList("SELECT * FROM formal_evaluation_case_original WHERE tenant_id=? AND registration_id=? FOR UPDATE",a.context().tenant_id(),registration));var j=jobs.original(a,text(row,"run_id"));if(a.actorId().equals(text(row,"created_by"))||!text(row,"receipt_sha256").equals(text(request,"registration_sha256")))deny();var grant=authorize(a,j,"agent.publish");var original=parser.readTree(text(row,"canonical_original"));same(hash(original),text(parser.readTree(text(row,"canonical_receipt")),"original_sha256"));schema.validate("Case",original);same(FormalEvaluationStageInputSchema.version(request),FormalEvaluationStageInputSchema.version(original));same(FormalEvaluationStageInputSchema.version(original),text(row,"schema_version"));same(schema.digest(FormalEvaluationStageInputSchema.version(original)),text(row,"schema_manifest_sha256"));scope(j,node(j,text(row,"step_id")),original);requireRules(a,original);verifyAudit(j,row,"registration_id","evaluation.case.registered");
   var prior=db.queryForList("SELECT * FROM formal_evaluation_case_approval WHERE tenant_id=? AND registration_id=?",j.tenantId(),registration);if(!prior.isEmpty()){same(a.actorId(),one(prior).get("created_by"));var saved=parser.readTree(text(one(prior),"canonical_receipt"));same(request,saved.required("request"));verifyAudit(j,one(prior),"approval_id","evaluation.case.approved");return saved;}
   String id=UUID.randomUUID().toString();var receipt=json.object().put("approval_id",id).put("registration_id",registration).put("registration_sha256",text(row,"receipt_sha256")).put("created_by",a.actorId());receipt.set("grant",AgentPublicationWitness.tree(grant));receipt.set("request",request.deepCopy());audit(j,a.actorId(),id,"evaluation.case.approved",json.canonical(receipt));changed(db.update("INSERT INTO formal_evaluation_case_approval (tenant_id,project_id,run_id,step_id,registration_id,approval_id,canonical_receipt,receipt_sha256,created_by,created_at,classification,schema_version,schema_manifest_sha256) VALUES (?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP(6),?,?,?)",j.tenantId(),j.projectId(),j.runId(),row.get("step_id"),registration,id,json.canonical(receipt),hash(receipt),a.actorId(),j.classification(),FormalEvaluationStageInputSchema.version(original),schema.digest(FormalEvaluationStageInputSchema.version(original))));return receipt;
  }).get());
 }
 void requireAuthor(EnterpriseAccess.Admission a,String context,JsonNode original)throws Exception{human(a,context);schema.validate("Case",original);var j=jobs.original(a,text(original,"run_id"));if(!j.actorId().equals(a.actorId()))deny();authorize(a,j,"agent.author");scope(j,node(j,text(original,"step_id")),original);requireRules(a,original);}
 record Original(FormalEvaluationJobs.Job job,FormalEvaluationJobs.NodeRow node,PermissionProtocol.Basis artifact,JsonNode document,JsonNode receipt,FormalEvaluationContextPackages.Plan plan,String witness){}
 Original require(EnterpriseAccess.Admission a,String run,String step)throws Exception{
  FormalEvaluationExecutionAdmission.current(a);var j=jobs.original(a,run);var n=node(j,step);var row=one(rows(j.tenantId(),run,step));var approval=one(db.queryForList("SELECT * FROM formal_evaluation_case_approval WHERE tenant_id=? AND registration_id=?",j.tenantId(),row.get("registration_id")));
  for(var r:List.of(row,approval)){same(j.projectId(),r.get("project_id"));same(run,r.get("run_id"));same(step,r.get("step_id"));same(text(row,"schema_version"),r.get("schema_version"));same(schema.digest(text(row,"schema_version")),r.get("schema_manifest_sha256"));same(hash(parser.readTree(text(r,"canonical_receipt"))),r.get("receipt_sha256"));}
  if(row.get("created_by").equals(approval.get("created_by")))deny();var receipt=parser.readTree(text(row,"canonical_receipt"));var decision=parser.readTree(text(approval,"canonical_receipt"));same(row.get("receipt_sha256"),text(decision,"registration_sha256"));same(n.nodeSha256(),text(receipt,"node_sha256"));requireActor(j,text(row,"created_by"),receipt.required("author_grant"),"agent.author");requireActor(j,text(approval,"created_by"),decision.required("grant"),"agent.publish");
  var artifact=new PermissionProtocol.Basis(text(row,"artifact_id"),text(row,"artifact_sha256"));var original=parser.readTree(text(row,"canonical_original"));same(hash(original),text(receipt,"original_sha256"));schema.validate("Case",original);same(text(row,"schema_version"),FormalEvaluationStageInputSchema.version(original));same(text(row,"schema_version"),FormalEvaluationStageInputSchema.version(decision.required("request")));scope(j,n,original);requireRules(a,original);requireLineage(artifact,original);verifyAudit(j,row,"registration_id","evaluation.case.registered");verifyAudit(j,approval,"approval_id","evaluation.case.approved");var plan=packages.plan(a,a.context().context_revision(),j.projectId(),artifact,FormalEvaluationStageInputSchema.caseRef(text(row,"schema_version")),schema.digest(text(row,"schema_version")));var proof=json.object();proof.set("registration",receipt);proof.set("approval",decision);proof.set("artifact",json.tree(artifact));return new Original(j,n,artifact,original,proof,plan,json.canonical(proof));
 }
 boolean available(EnterpriseAccess.Admission a,String run,String step)throws Exception{var j=jobs.original(a,run);node(j,step);var rows=rows(j.tenantId(),run,step);return rows.size()==1&&db.queryForObject("SELECT COUNT(*) FROM formal_evaluation_case_approval WHERE tenant_id=? AND registration_id=?",Integer.class,j.tenantId(),rows.get(0).get("registration_id"))==1;}

 /** Exact approved originals are embedded in the physically registered case, not merely selectors. */
 JsonNode requireRules(EnterpriseAccess.Admission a,JsonNode original)throws Exception {
  var expected=selectedRules(original);var actual=new TreeMap<String,JsonNode>();
  for(var copy:original.required("rule_originals")){String id=text(copy,"rule_id");if(actual.put(id,copy)!=null)bad();}
  same(expected.keySet(),actual.keySet());var result=json.object().arrayNode();
  for(var entry:expected.entrySet()){var copy=actual.get(entry.getKey());same(json.tree(entry.getValue()),copy.required("rule_revision"));var approved=rules.require(a,entry.getValue(),true);same(json.tree(approved.request().content()),copy.required("content"));var item=result.addObject().put("rule_id",entry.getKey()).put("sha256",entry.getValue().content_sha256());item.set("rule_revision",json.tree(entry.getValue()));item.set("content",copy.required("content").deepCopy());}
  return result;
 }
 static SortedMap<String,PermissionProtocol.Basis> selectedRules(JsonNode original){
  var result=new TreeMap<String,PermissionProtocol.Basis>();var business=original.required("node_business_original");String kind=text(original,"node_kind");
  JsonNode values=switch(kind){case "N02"->business.required("completion_inputs");case "N05","N07"->business.required("rules");case "N06"->business.required("cross_file_inputs").required("rules");default->com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.arrayNode();};
  for(var value:values){var pin=basis(value.required("rule_revision"));var old=result.put(text(value,"rule_id"),pin);if(old!=null&&!old.equals(pin))bad();}return result;
 }
 private void requireLineage(PermissionProtocol.Basis artifact,JsonNode original){var graph=lineage.inspect(artifact.version_id(),new DependencyLineage.Limits(2048,8192));same(artifact.content_sha256(),graph.versions().get(artifact.version_id()).contentSha256());for(var pin:selectedRules(original).values()){var version=graph.versions().get(pin.version_id());if(version==null)bad();same(pin.content_sha256(),version.contentSha256());}requireBusinessAncestors(original.required("node_business_original"),graph,0);}
 private void requireBusinessAncestors(JsonNode value,DependencyLineage.VerifiedLineage graph,int depth){if(depth>64)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);if(value.isObject()){if(value.has("version_id")&&value.has("content_sha256")){var pin=basis(value);var version=graph.versions().get(pin.version_id());if(version==null)bad();same(pin.content_sha256(),version.contentSha256());}for(String field:List.of("source_version","document_revision","body_artifact_id","field_revision","evidence_revision")){var id=value.path(field);if(id.isTextual()&&!graph.versions().containsKey(id.asText()))bad();}}for(var child:value)requireBusinessAncestors(child,graph,depth+1);}
 private void audit(FormalEvaluationJobs.Job j,String actor,String id,String action,String payload){
  changed(db.update("INSERT INTO audit_event (tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES (?,?,?,?,?,?,'SUCCESS',?,?,'1.0.0',?,?,UTC_TIMESTAMP(6),?)",j.tenantId(),j.projectId(),id,actor,action,payload,id,j.runId(),json.manifestSha256(),actor,j.classification()));
  changed(db.update("INSERT INTO outbox_event (tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES (?,?,?,1,?,?,UTC_TIMESTAMP(6))",j.tenantId(),id,id,action,payload));
 }
 private void verifyAudit(FormalEvaluationJobs.Job j,Map<String,Object> row,String idField,String action){
  same(text(row,"canonical_receipt"),one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action=? AND result='SUCCESS' AND request_id=? AND trace_id=? AND schema_manifest_sha256=?",(rs,n)->rs.getString(1),j.tenantId(),j.projectId(),row.get(idField),row.get("created_by"),action,row.get(idField),j.runId(),json.manifestSha256())));
  same(text(row,"canonical_receipt"),one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type=?",(rs,n)->rs.getString(1),j.tenantId(),row.get(idField),row.get(idField),action)));
 }
 public JsonNode read(ApplicationSessionIdentity.Verified subject,String context,String run,String step)throws Exception{return access.execute(subject,a->ThrowingSupplier.of(()->{human(a,context);var j=jobs.original(a,run);authorize(a,j,"agent.author");var row=one(rows(j.tenantId(),run,step));verifyAudit(j,row,"registration_id","evaluation.case.registered");var result=json.object();result.set("registration",view(row));result.set("case",parser.readTree(text(row,"canonical_original")));var approvals=db.queryForList("SELECT * FROM formal_evaluation_case_approval WHERE tenant_id=? AND registration_id=?",j.tenantId(),row.get("registration_id"));if(approvals.isEmpty())result.put("state","WAITING_INDEPENDENT_APPROVAL");else{require(a,run,step);result.put("state","APPROVED");result.set("approval",parser.readTree(text(one(approvals),"canonical_receipt")));}return result;}).get());}
 private void requireActor(FormalEvaluationJobs.Job j,String actor,JsonNode proof,String action)throws Exception{var original=parser.treeToValue(proof,PermissionProtocol.GrantRow.class);var member=one(permissions.targetMember(actor));var binding=one(permissions.targetBinding(actor));var now=permissions.databaseTime();if(!j.tenantId().equals(member.tenantId())||!actor.equals(member.userId())||!"ACTIVE".equals(member.status())||member.validFrom().isAfter(now)||member.validTo()!=null&&!member.validTo().isAfter(now)||!"ACTIVE".equals(binding.status())||!identities.active(new AuthenticatedIdentityBinding.View(binding.mode(),binding.userId(),binding.issuer(),binding.subject())))deny();var grant=one(permissions.currentGrant(original.grantId()));same(proof,AgentPublicationWitness.tree(grant));grants.requireResource(new PermissionProtocol.Scope(j.tenantId(),j.projectId(),"PROJECT",j.projectId()),actor,binding.mode(),action,"AGENT_PUBLICATION",List.of(grant),now);}
 private void scope(FormalEvaluationJobs.Job j,FormalEvaluationJobs.NodeRow n,JsonNode original){same("EVALUATION_VERIFICATION",text(original,"purpose"));same(j.tenantId(),text(original,"tenant_id"));same(j.projectId(),text(original,"project_id"));same(j.runId(),text(original,"run_id"));same(n.stepId(),text(original,"step_id"));same(n.nodeSha256(),text(original,"node_sha256"));same(n.node().nodeKind(),text(original,"node_kind"));same(n.node().cell().sampleId(),text(original,"sample_id"));same(json.tree(n.node().cell().candidate()),original.required("candidate"));same(json.tree(n.node().cell().policy()),original.required("policy"));}
 private static FormalEvaluationJobs.NodeRow node(FormalEvaluationJobs.Job j,String step){var n=one(j.nodes().stream().filter(x->x.stepId().equals(step)).toList());if(!Set.of("N02","N03","N04","N05","N06","N07").contains(n.node().nodeKind()))deny();return n;}
 private PermissionProtocol.GrantRow authorize(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job j,String action)throws Exception{return resources.require(a,new PermissionProtocol.Scope(j.tenantId(),j.projectId(),"PROJECT",j.projectId()),action,"AGENT_PUBLICATION");}
 private void lock(FormalEvaluationJobs.Job j,String step){one(db.queryForList("SELECT step_id FROM formal_evaluation_node WHERE tenant_id=? AND run_id=? AND step_id=? FOR UPDATE",j.tenantId(),j.runId(),step));}
 private List<Map<String,Object>> rows(String t,String r,String s){return db.queryForList("SELECT * FROM formal_evaluation_case_original WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",t,r,s);}
 private JsonNode view(Map<String,Object> row)throws Exception{var v=(com.fasterxml.jackson.databind.node.ObjectNode)parser.readTree(text(row,"canonical_receipt"));v.put("registration_sha256",text(row,"receipt_sha256"));return v;}
 private static void human(EnterpriseAccess.Admission a,String context){if(a.evaluationWorker()||!context.equals(a.context().context_revision()))deny();}
 private String hash(JsonNode v)throws Exception{return WireValues.sha256(ContentReadAuthorization.canonicalBytes(v));}
 private static PermissionProtocol.Basis basis(JsonNode n){return new PermissionProtocol.Basis(text(n,"version_id"),text(n,"content_sha256"));}
 private static String text(JsonNode n,String k){return n.required(k).textValue();}private static String text(Map<String,Object> n,String k){return (String)n.get(k);}private static <T>T one(List<T> xs){if(xs.isEmpty())throw new TenantAccessException(ErrorCode.STEP_NOT_READY);if(xs.size()!=1)bad();return xs.get(0);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void changed(int n){if(n!=1)bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
